// CSD_RATIONALE_BEGIN
// Root-cause analysis of attempt 28 failures vs. best (attempt 24, 34.7% acc, 79.6% syntax):
//
// 1. mode_K (13/34 wrong): Long repetitive constrained spans from `CloseSpanWithinBudget`,
//    which tracks the LONGEST complete prefix and keeps generating "+1+1+1..." or "/2/2/2/"
//    because each extension is also a complete arithmetic expression.
//    FIX: Use `CloseSpanIfComplete` (closes at FIRST complete parse) in a step-by-step loop.
//
// 2. final_span_invalid (17/49): The constrained span contains `{n}`, `{x}`, `**`, or LaTeX.
//    The CSD parser apparently admits brace-enclosed identifiers (model's template notation)
//    as valid arithmetic tokens, so hard masking alone doesn't block them.
//    FIX: `SafePenalizedConstrainedStep` with `["{", "}"]` penalty reduces but doesn't hard-block.
//
// 3. final_span_unclosed (3/49): After a correct `<<int(expr)>>` the model emits another `<<`
//    which hits budget. Natural `<<` detection re-enters constrained mode for this second span,
//    and with `CloseSpanIfComplete` + penalized steps it will close cleanly.
//
// 4. Repetition loops (5/49): Penalizing `{`, `}` and using immediate-close strategy prevents
//    the parser from wandering into long degenerate arithmetic continuations.
//
// Strategy: Classic `CloseSpanIfComplete`-in-loop pattern (like the first verified example)
// with TWO upgrades:
//   A. First constrained token: `SafeBoostedConstrainedStep` boosting `"int"` so the model
//      starts the span with `int(` instead of a bare subexpression.
//   B. Subsequent constrained tokens: `SafePenalizedConstrainedStep` penalizing `{` and `}`.
//
// This replaces `GenerateWithPrefixAndManagedSpan` (which uses `AdaptiveConstrainedStep` /
// `ConfidenceGatedStep` internally and cannot inject per-token logit edits).
//
// Natural `<<` detection is kept (RenderedEndsWith); no forced-open to avoid mid-context garbage.
// Guidance matches attempt 24's winning formulation (short, example-driven, int() explicit).
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initialization: insideConstrainedOut := insideConstrained, currentConstrainedOut :=
//   currentConstrained. Precondition guarantees insideConstrained ==>
//   parser.IsValidPrefix(currentConstrained), so invariant holds on entry.
//
//   Unconstrained branch: insideConstrainedOut is false throughout this branch;
//   the invariant is vacuously true. When RenderedEndsWith fires we set
//   currentConstrainedOut := [] and parser.IsValidPrefix([]) holds from the
//   `requires parser.IsValidPrefix([])` precondition. ✓
//
//   Constrained branch — closed path: CloseSpanIfComplete's postcondition guarantees
//   !insideConstrainedOut ==> currentConstrainedOut == [] (span exits, implication becomes
//   vacuously true). ✓
//
//   Constrained branch — not-closed path, first token (|currentConstrainedOut| == 0):
//   SafeBoostedConstrainedStep's postcondition guarantees that the returned token `next`
//   (when not EOS) satisfies `parser.IsValidPrefix(currentConstrainedOut + [next])`.
//   IsTokenValidNext confirms this, then AppendConstrainedToken appends preserving validity. ✓
//
//   Constrained branch — not-closed path, later tokens: SafePenalizedConstrainedStep has the
//   same hard-mask postcondition as ConstrainedStep: next == eosToken or
//   parser.IsValidPrefix(currentConstrainedOut + [next]). IsTokenValidNext confirms;
//   AppendConstrainedToken preserves validity. ✓
//
// progress: |generated| <= |generatedPrefix| + steps
//
//   Unconstrained branch: each iteration increments steps by 1 and appends at most 1 token
//   (EOS is not appended). So |generated| - |generatedPrefix| grows by at most 1 per iteration,
//   matching the +1 to steps. ✓
//
//   Constrained branch (closed): CloseSpanIfComplete costs +1 step (the >> delimiter token
//   appended by CloseConstrainedSpan internally); steps increments by 1, generated grows by
//   exactly 1. Bound preserved. ✓
//
//   Constrained branch (not-closed): CloseSpanIfComplete cost is +0 when it leaves the span
//   open; the subsequent SafeBoostedConstrainedStep or SafePenalizedConstrainedStep each
//   cost exactly +1 token-step. Combined: steps += 1 and generated grows by at most 1
//   (via AppendConstrainedToken, only when valid is true; otherwise generated is unchanged
//   while steps still increases by 1, making the bound easier to satisfy). ✓
//
//   Liveness (maxSteps > 0 ==> cost > 0): every loop iteration increments steps by 1,
//   so after the first iteration cost >= 1 > 0. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  helpers.AppendTaskGuidance(lm, "Solve step by step. At the very end write <<int(expr)>> where expr uses only: variable names (no braces), numbers, +, -, *, /, //, %, (, ), int(). Exactly one <<int(expr)>> at the end. Example: <<int(n*price+base)>>. No {braces}, no LaTeX, no **.");

  var steps: nat := 0;

  while steps < maxSteps
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    if !insideConstrainedOut {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    } else {
      // Check completion first; cost is +1 when closed, +0 when open.
      // The combined step budget for this branch is always 1.
      var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      steps := steps + 1;
      if closed {
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
      } else {
        // Build the constrained prompt: everything up to (but not including) the constrained suffix.
        var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next: Token;
        if |currentConstrainedOut| == 0 {
          // First token in span: boost "int" to steer toward int(expr) form.
          next := helpers.SafeBoostedConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, ["int"], 6.0, eosToken);
        } else {
          // Subsequent tokens: penalize brace characters to prevent {var} style identifiers.
          next := helpers.SafePenalizedConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, ["{", "}"], 8.0, eosToken);
        }
        if next == eosToken {
          break;
        }
        var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
        if valid {
          var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      }
    }
  }

  cost := steps;
}

